/* Drawing grammar v1. Anatomy is generated once; all drawing stages consume it. */
(function(root){
const rng=seed=>()=>{seed|=0;seed=seed+0x6D2B79F5|0;let t=Math.imul(seed^seed>>>15,1|seed);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296;};
const subjects=[
 ['pine','Pine','Growth & branching',['A tapering leader bends slightly with exposure. Branches attach to this trunk.','Branch reach increases toward the lower crown; left and right branches differ in age and loss.','Secondary shoots follow their parent branch. Needle fans grow along those shoots, leaving air between them.','Cool shadow belongs beneath overlapping sprays. Short ink marks follow the needles, not a triangular outline.'],'Next: judge branch weight and negative spaces before adding more needles.'],
 ['broadleaf','Broadleaf tree','Growth & branching',['The trunk forks into several load-bearing limbs.','Each limb divides into finer growth; leaf masses gather at the ends.','Clusters overlap but preserve openings around the trunk.','Shade sits beneath the clusters; broken outlines describe only selected edges.'],'Next: distinguish oak, apple and willow architecture.'],
 ['shrub','Shrub','Growth & branching',['Multiple stems emerge from a common root crown.','Short shoots carry overlapping small leaf masses.','The lower, sheltered interior is darker than exposed tips.','Visible stems connect the foliage to the ground.'],'Next: species-specific buds, leaves and seasonal growth.'],
 ['barn','Barn','Construction & weather',['A structural box supports a pitched roof and projecting eaves.','Roof planes meet at a ridge; openings align with the frame.','Board marks follow construction direction and stop at doors and corners.','Shade follows the far roof plane, eaves and recessed openings. Weathering is patchy, not a striped fill.'],'Next: study roof proportions, repairs and material-specific weathering.'],
 ['farmhouse','Farmhouse','Construction & weather',['A pitched roof sits over a small house frame.','A porch is supported by posts, with a visible sheltered entrance.','Windows and chimney are attached to the wall or roof structure.','The porch recess and far roof carry shade; ink accents joints and overhangs.'],'Next: develop a specific architectural character rather than a generic house.'],
 ['fence','Fence & gate','Construction & load',['Posts follow changing ground height.','Each rail spans two posts, with its endpoints attached.','A braced gate occupies one bay; its diagonal supports the frame.','Post thickness, rail sag and joint wear vary within a coherent construction.'],'Next: distinguish timber rails, wire tension and repaired sections.'],
 ['reeds','Reeds','Growth & habitat',['Stems emerge from several compact root clumps.','Shared wind bends stems, with different heights and stiffness.','Leaves peel away from stems; seed heads terminate selected mature stalks.','Darkness gathers at the roots and overlapping leaves; open water stays clear.'],'Next: tune clump density and the transition from wet bank to open ground.'],
 ['garden','Kitchen garden','Planting & tending',['Short beds leave working space around and between them.','Timber edges contain soil; plants occupy imperfect staggered planting positions.','Broad leaves, climbing beans and feathery foliage require different marks.','Shadow appears under foliage and bed edges, with bare soil remaining visible.'],'Next: give each crop its own growth stages and hand-tended irregularities.'],
 ['grass','Meadow grasses','Growth & habitat',['Grasses share a root crown, not a row of identical ticks.','Blades arch outward at different heights; some carry seed heads.','Small groups leave open ground between patches.','Older dry stems provide muted warm accents beneath green growth.'],'Next: compare short grazed grass, meadow and shaded woodland grass.'],
 ['rocks','Rocks','Mass & fracture',['Each stone has an irregular mass with a stable ground contact.','A few connected planes explain its volume.','Light catches upward faces; crevices and ground contact stay dark.','Cracks follow planes and terminate; avoid uniform outlines around every face.'],'Next: distinguish rounded stream stones from fractured outcrops.'],
 ['brook','Brook & banks','Flow & erosion',['Two banks contain a continuous watercourse.','The channel widens and bends; exposed gravel collects along selected margins.','Ripples follow the local direction of flow.','Darker bank edges suggest depth; pale broken reflections cross quiet water.'],'Next: derive bank shapes from flow and ground elevation.'],
 ['path','Path & ground','Use & wear',['An intended route connects two places.','Width changes at bends and junctions, rather than staying a perfect tube.','Worn center ground differs from vegetated edges.','Wheel and foot traces follow travel; stones and tufts gather toward margins.'],'Next: distinguish footpaths, cart tracks and muddy gate approaches.']
].map(([id,name,family,rules,next])=>({id,name,family,rules,next}));

subjects.unshift({id:'old-tree',name:'Ancient cedar',family:'Hero glyph · age & weight',rules:['Roots spread into the ground before the trunk turns upward.','Heavy limbs grow from the twisting trunk; their tips lift beneath separate canopy shelves.','A loaded round brush builds the wood. Dry bristles follow its bends and leave pale scars.','Foliage is laid in short directional dabs. Dark lower strokes support lighter tips; gaps reveal the limbs.'],next:'Next: critique the balance of the trunk, the weight of each limb and the open spaces between crowns.'});
const brushes={wash:{label:'Wet wash',opacity:.19,grain:.07},round:{label:'Loaded round',opacity:.64,grain:.03},dry:{label:'Dry bristle',opacity:.47,grain:.35},flick:{label:'Needle flick',opacity:.65,grain:.1}};
function build(id,seed){
 const r=rng(seed),layers={structure:[],wash:[],shade:[],ink:[],detail:[]},strokes=[];
 const mix=(a,b,t)=>a+(b-a)*t;
 function stroke(layer,points,width,color,brush='round',pressure=[.35,1,.02]){
  const n=24, samples=[],b=brushes[brush],start=points[0],control=points[1],end=points[2]||points[1];
  for(let i=0;i<=n;i++){let t=i/n,u=1-t,x=u*u*start[0]+2*u*t*control[0]+t*t*end[0],y=u*u*start[1]+2*u*t*control[1]+t*t*end[1],dx=2*u*(control[0]-start[0])+2*t*(end[0]-control[0]),dy=2*u*(control[1]-start[1])+2*t*(end[1]-control[1]),len=Math.hypot(dx,dy)||1,p=t<.38?mix(pressure[0],pressure[1],t/.38):mix(pressure[1],pressure[2],(t-.38)/.62);samples.push({x,y,nx:-dy/len,ny:dx/len,w:width*p*(.94+r()*.12)});}
  const marks=[],ribbon=(offset,scale,opacity)=>{const a=[],z=[];for(const q of samples){let w=q.w*scale/2*(1-b.grain*r());a.push([q.x+q.nx*(q.w*offset+w),q.y+q.ny*(q.w*offset+w)]);z.unshift([q.x+q.nx*(q.w*offset-w),q.y+q.ny*(q.w*offset-w)]);}marks.push({tag:'path',a:{d:'M'+a.concat(z).map(p=>p.map(v=>v.toFixed(3)).join(',')).join('L')+'Z',fill:color,opacity}});};
  if(brush==='dry'){for(let j=0;j<7;j++)if(r()>.12)ribbon((j-3)/7,.055+r()*.06,b.opacity*(.55+r()*.5));}
  else {ribbon(0,1,b.opacity);if(brush==='wash'){ribbon(-.38,.06,.08);ribbon(.37,.08,.07);}else ribbon(-.18,.12,.12);}
  const record={layer,brush,width,color,pressure,points,marks};strokes.push(record);layers[layer].push(...marks);
  const guide={tag:'path',a:{d:`M${start}Q${control} ${end}`,fill:'none',stroke:'#9a866b','stroke-width':.16,opacity:.38}};if(width>1.4)layers.structure.push(guide);
 }
 const S=(layer,a,c,b,w,col,brush='round',pressure)=>stroke(layer,[a,c,b],w,col,brush,pressure);
 const line=(layer,a,b,w,col,brush='dry')=>S(layer,a,[(a[0]+b[0])/2,(a[1]+b[1])/2],b,w,col,brush);
 function tuft(x,y,size,col='#728967',count=9){for(let k=0;k<count;k++){let a=-Math.PI+r()*Math.PI,l=size*(.35+r()*.65);S('wash',[x+(r()-.5)*size*.5,y],[x+Math.cos(a)*l*.45,y+Math.sin(a)*l*.4],[x+Math.cos(a)*l,y+Math.sin(a)*l],size*.23,col,'round',[.65,1,.01]);}for(let k=0;k<4;k++)line('shade',[x-size*.5+r()*size,y],[x-size*.3+r()*size,y-1-r()*2],size*.2,'#304a3d','dry');}
 function wood(a,c,b,w){S('wash',a,c,b,w,'#857052','round',[.9,1,.2]);S('shade',[a[0]+w*.18,a[1]],c,b,w*.6,'#3e4031','round',[.8,1,.04]);S('ink',a,c,b,w*.65,'#d0b48a','dry',[.5,.7,.02]);S('detail',a,[c[0]-w*.1,c[1]],b,.28,'#35392e','dry');}
 if(['pine','old-tree','broadleaf','shrub'].includes(id)){
 const old=id==='old-tree',shrub=id==='shrub',pine=id==='pine';
 S('wash',[21,101],[61,93],[103,101],8,'#788563','wash');
 if(old){wood([49,99],[71,75],[57,57],14);wood([61,74],[49,48],[60,13],9);wood([53,94],[37,99],[15,104],5);wood([55,96],[78,101],[99,104],4);wood([55,83],[76,65],[94,65],7);wood([56,78],[39,65],[23,61],6);wood([57,60],[40,40],[16,39],5);wood([57,48],[78,39],[103,40],5);wood([58,36],[44,23],[30,22],4);wood([55,27],[78,17],[90,19],3);
 for(const [x,y,w,ax,ay] of [[21,38,25,16,39],[42,27,24,30,22],[70,18,28,90,19],[91,39,26,103,40],[72,48,22,57,48],[23,60,29,23,61],[94,64,23,94,65],[64,12,18,60,13]]){
 for(let k=0;k<5;k++){let xx=x+(k/4-.5)*w;wood([ax,ay],[xx,ay-2],[xx,y-1],.65);}
 for(let k=0;k<28;k++){let xx=x+(r()-.5)*w,yy=y-2-r()*4;S('shade',[xx-3,yy+2],[xx,yy+1],[xx+4,yy+1],2.5,'#3d5543','round',[.15,1,.05]);S('wash',[xx-3,yy],[xx,yy-2-r()*2],[xx+4,yy-1],2+r()*1.8,k%3?'#819775':'#a8b590','round',[.1,1,.02]);S('detail',[xx-2,yy],[xx,yy-1],[xx+3,yy-1],.8,'#c0c49c','dry');}
 }

 }else{wood([59,98],[56,63],[58,shrub?55:13],shrub?3:5);let count=shrub?7:pine?10:7;for(let i=0;i<count;i++){let t=i/count,y=shrub?84:23+t*62,side=i%2?-1:1,reach=shrub?20:pine?8+t*31:18+r()*19,x=58+side*reach;wood([58,y+7],[58+side*reach*.4,y+13],[x,y],.7+t*1.7);if(pine){for(let j=1;j<7;j++){const q=j/7,bx=58+(x-58)*q,by=y+8*(1-q);for(let k=0;k<8;k++){const dx=side*(1+r()*4),dy=2+r()*5;S('wash',[bx,by],[bx+dx*.4,by-dy*.4],[bx+dx,by-dy],.6+r()*.55,k%3?'#506e49':'#8fa071','flick');}}}else for(let k=0;k<4;k++)tuft(x+(r()-.5)*15,y-2-r()*8,shrub?9:14);}}
 }else if(['barn','farmhouse'].includes(id)){
 const house=id==='farmhouse';for(let x=22;x<98;x+=3.3)S('wash',[x,53],[x+(r()-.5),71],[x,89],5,house?'#c5b791':'#a15b42','wash',[.85,1,.75]);
 for(let j=0;j<12;j++){let y=27+j*2.2;line('wash',[35-(y-27)*.65,y],[81+(y-27)*.68,y],4.5,'#68745e','wash');}for(let x=25;x<97;x+=5)line('ink',[x,57],[x+(r()-.5),88],.65,'#685943','dry');
 line('shade',[22,55],[98,55],3,'#3f4937','round');for(const [a,b] of [[[16,53],[35,26]],[[35,26],[81,26]],[[81,26],[101,54]]])line('ink',a,b,.65,'#424a38','dry');
 for(let x=49;x<68;x+=2.5)line('shade',[x,65],[x,89],3.5,'#414e3d','round');line('ink',[48,65],[68,88],.9,'#d8bd8c','dry');line('ink',[68,65],[48,88],.9,'#d8bd8c','dry');
 for(let x of [30,80]){for(let j=0;j<4;j++)line('shade',[x+j*2,63],[x+j*2,72],2.7,'#506458','round');line('ink',[x+3,62],[x+3,74],.5,'#dfd6b3','round');line('ink',[x-1,68],[x+8,68],.5,'#dfd6b3','round');}
 if(house){line('wash',[33,63],[78,63],5,'#8d9173','round');wood([34,64],[34,77],[34,92],1.5);wood([77,64],[77,77],[77,92],1.5);}S('wash',[15,94],[68,89],[109,95],8,'#6e7858','wash');
 }else if(id==='fence'){
 let posts=Array.from({length:5},(_,i)=>[13+i*23,76+Math.sin(i)*4]);for(let i=0;i<5;i++){let [x,y]=posts[i];wood([x,y],[x-.5,y-16],[x+(r()-.5)*2,y-32],2.8);if(i)for(let h of [10,24])wood([posts[i-1][0],posts[i-1][1]-h],[(x+posts[i-1][0])/2,y-h+1],[x,y-h],2);}wood([59,53],[70,61],[82,69],1.6);
 }else if(['reeds','grass'].includes(id)){
 for(const [x,y]of [[25,89],[60,94],[91,85]]){S('wash',[x-10,y],[x,y+2],[x+12,y],5,'#7a8860','wash');for(let i=0;i<18;i++){let a=x+(r()-.5)*8,h=(id==='reeds'?22:9)+r()*29,b=a+(r()-.35)*24;S('wash',[a,y],[a,y-h*.7],[b,y-h],.6+r()*.9,i%4?'#748358':'#a39561','flick',[.9,.65,0]);if(id==='reeds'&&i%5===0)line('ink',[b,y-h],[b+1,y-h-6],1.7,'#806744','dry');}}
 }else if(id==='garden'){
 for(const [x,y]of [[16,26],[67,27],[20,65],[70,66]]){for(let j=0;j<7;j++)line('wash',[x,y+j*2.6],[x+30,y+j*2.6],4,'#a28a66','wash');wood([x,y+20],[x+15,y+20],[x+31,y+20],1.2);wood([x,y],[x,y+10],[x,y+20],1);for(let k=0;k<9;k++)tuft(x+5+(k%3)*10+(r()-.5)*2,y+5+Math.floor(k/3)*6,3+r()*2,'#6b8651',5);}
 }else if(id==='rocks'){
 for(const [x,y,w]of [[32,73,23],[79,77,21],[63,43,15]]){for(let j=0;j<9;j++){let t=j/8;line('wash',[x-w*(.6+t*.3),y-w*.6+t*w*.7],[x+w*(.3+t*.7),y-w*.8+t*w],w*.18,'#9b9e87','wash');}for(let j=0;j<7;j++)line('shade',[x+j*w*.1,y-w*.5],[x+w*.2+j*w*.1,y+w*.1],w*.2,'#596c5b','dry');line('ink',[x,y-w*.65],[x-w*.2,y-w*.15],.6,'#4c5949','dry');S('shade',[x-w,y+3],[x,y+5],[x+w,y+2],3,'#667052','dry');}
 }else{let water=id==='brook';for(let i=0;i<12;i++){let y=42+i*1.6;S('wash',[0,y],[45,y-23],[62,y+5],3.6,water?'#91b3aa':'#c7ad80','wash',[.8,1,.8]);S('wash',[62,y+5],[92,y+17],[120,y-3],3.6,water?'#91b3aa':'#c7ad80','wash',[.8,1,.8]);}for(let i=0;i<30;i++){let x=r()*120,y=45+Math.sin(x/19)*9+r()*11;line('ink',[x,y],[x+2+r()*7,y-.8],.4,water?'#e1e6cf':'#99815d','dry');}for(let i=0;i<12;i++)tuft(i*11,71+Math.sin(i)*5,3,'#768762',4);}
 return {id,seed,layers,strokes};
}
function mount(svg,model,mode,progress=1){svg.replaceChildren();const ns='http://www.w3.org/2000/svg',chosen=mode==='structure'?['structure']:mode==='wash'?['wash']:mode==='shade'?['wash','shade']:mode==='ink'?['ink','detail']:['wash','shade','ink','detail'];
 const append=(parent,mark)=>{const e=document.createElementNS(ns,mark.tag);for(const [k,v]of Object.entries(mark.a))e.setAttribute(k,v);parent.append(e);};
 if(mode==='structure'){for(const m of model.layers.structure)append(svg,m);return;}
 const selected=model.strokes.filter(s=>chosen.includes(s.layer)),limit=Math.ceil(selected.length*progress);selected.slice(0,limit).forEach((s,i)=>{const g=document.createElementNS(ns,'g');g.setAttribute('data-brush',s.brush);g.setAttribute('data-stroke',i+1);const title=document.createElementNS(ns,'title');title.textContent=`${i+1}. ${brushes[s.brush].label} · ${s.layer} · width ${s.width.toFixed(1)} · pressure ${s.pressure.join(' → ')}`;g.append(title);for(const mark of s.marks)append(g,mark);svg.append(g);});return {count:selected.length,visible:limit,last:selected[limit-1]};}
root.DrawingLanguage={subjects,brushes,build,mount};if(typeof module!=='undefined')module.exports=root.DrawingLanguage;
})(typeof window!=='undefined'?window:globalThis);
